import { readArtifact, writeArtifact } from './event-store.js';
import { checkAbort } from './client.js';

// Lifetime W/L costs one packed word per 32 days on a cold browser. Once
// cached, only the unfinished word and new days are read. No global log scan.
export async function coinflipStats(s, signal) {
  const last=Number(await s.field('COINFLIP','flipsClaimableDay'));
  const key=`flip-record:${s.client.chain.id}:${s.client.address('COINFLIP')}`;
  let saved=await readArtifact(key);
  if(saved&&(saved.throughDay>last||saved.block>s.block.number||(await s.client.header(saved.block,signal)).hash!==saved.hash))saved=null;
  let wins=saved?.wins??0,losses=saved?.losses??0,recent=saved?.recent??[],checkpoint=null;
  const first=(saved?.throughDay??0)+1;
  for(let base=first>>5;base<=(last>>5);base+=25){
    checkAbort(signal);const words=await Promise.all(Array.from({length:Math.min(25,(last>>5)-base+1)},(_,i)=>s.field('COINFLIP','coinflipDayResultPacked',base+i)));
    for(const [i,word]of words.entries()){
      const start=Math.max(first,(base+i)*32),end=Math.min(last,(base+i)*32+31);
      for(let day=start;day<=end;day++){
        const byte=Number(word>>BigInt((day&31)*8)&255n);if(!byte)continue;
        const win=byte>=50;if(win)wins++;else losses++;
        recent=[{day,win,rewardPercent:byte},...recent].slice(0,26);
      }
      if(end%32===31)checkpoint={throughDay:end,wins,losses,recent};
    }
  }
  if(checkpoint){await s.verify(signal);writeArtifact(key,{...checkpoint,block:s.block.number,hash:s.block.hash});}
  return {wins,losses,recent};
}
